BEGIN;
CREATE INDEX idx_identities_user ON identity.identities(user_id); CREATE INDEX idx_memberships_user ON tenant.memberships(user_id); CREATE INDEX idx_offers_tenant_status ON affiliate.offers(tenant_id,status); CREATE INDEX idx_clicks_offer_time ON tracking.clicks(offer_id,occurred_at DESC); CREATE INDEX idx_conversions_tenant_status ON tracking.conversions(tenant_id,status); CREATE INDEX idx_conversions_correlation ON tracking.conversions(correlation_id); CREATE INDEX idx_ledger_entries_tx ON ledger.entries(transaction_id); CREATE INDEX idx_ledger_entries_account ON ledger.entries(account_id); CREATE INDEX idx_ledger_tx_correlation ON ledger.transactions(correlation_id); CREATE INDEX idx_payout_status ON payment.payout_requests(tenant_id,status); CREATE INDEX idx_ai_decisions_correlation ON ai.decisions(correlation_id); CREATE INDEX idx_audit_correlation ON audit.events(correlation_id); CREATE INDEX idx_outbox_unpublished ON core.outbox_events(occurred_at) WHERE published_at IS NULL; CREATE INDEX idx_evidence_subject ON evidence.objects(tenant_id,subject_type,subject_id);
COMMIT;
